{
  "strategy": {
    "id": "roll_condor_us",
    "label": "US Condor",
    "mode": "symbol_selector",
    "market": "US",
    "symbols": [
      "AAPL"
    ],
    "timeframe": "1d",
    "trading_calendar": "XNYS"
  },
  "selector": {
    "target_dte": "30-60",
    "strike_rule": "by_delta",
    "short_delta": "0.18-0.25",
    "wing_delta": "0.05-0.10",
    "width": {
      "min": 2,
      "max": 8
    },
    "iv_rank_min": 50,
    "min_credit_of_width": 0.33,
    "candidate_top_k": 3,
    "tie_breakers": [
      "spread",
      "oi",
      "dte",
      "round_strike"
    ]
  },
  "roll_policy": {
    "enabled": true,
    "manage_at_dte_lte": 21,
    "roll_to_dte": "30-60",
    "threatened_side_only": true,
    "keep_width": true,
    "delta_retarget": {
      "put": "0.16-0.25",
      "call": "0.20-0.30"
    },
    "min_expected_return_annualized": 0.15,
    "liquidity_gate": {
      "min_oi": 500,
      "min_volume": 100,
      "max_spread_pct": 0.08
    },
    "events": {
      "avoid_earnings": true,
      "ex_div_assignment_check": true
    }
  },
  "exit_policy": {
    "hard_exit_dte_lte": 7,
    "tp_sl": {
      "credit": {
        "tp_of_max": [
          0.25,
          0.5
        ],
        "sl_x_credit": [
          1.5,
          2.0
        ]
      }
    },
    "trailing_after_profit": {
      "trigger": 0.8,
      "drawdown": 0.2
    },
    "structure": {
      "max_loss_hit_pct": 0.85
    },
    "liquidity_fallback_exit": true
  },
  "wing_policy": {
    "enabled": true,
    "same_expiry": true,
    "wing_delta": "0.05-0.10",
    "max_cost_pct_of_credit": 0.4,
    "min_credit_of_width_after_wing": 0.33
  },
  "execution": {
    "combo_order": true,
    "price_preference": "mid",
    "price_offset_bps": 5,
    "retry": {
      "max_attempts": 2,
      "backoff_sec": 1
    },
    "fill_guard": {
      "max_spread_pct": 0.12,
      "min_oi": 100,
      "min_volume": 10
    },
    "reject_if_guard_fails": true
  },
  "fees": {
    "commission_per_contract": 0.65,
    "exchange_fees_per_contract": 0.15,
    "exercise_assignment_fee": 5.0
  },
  "slippage": {
    "model": "mid_bps",
    "mid_bps": 5
  },
  "entry": {
    "liquidity": {
      "min_oi": 500,
      "min_volume": 100,
      "max_spread_pct": 0.08
    },
    "event_gate": {
      "avoid_earnings": true
    },
    "signals": {
      "trend": "breakout_or_ma",
      "allow_event_play": false
    }
  },
  "monitor": {
    "manage_triggers": [
      "time",
      "pnl",
      "delta",
      "price_touch",
      "event",
      "liquidity"
    ],
    "metrics": [
      "pnl",
      "annualized_return",
      "theta",
      "margin_usage"
    ]
  },
  "tolerances": {
    "dte_snap_days": 2,
    "delta_snap": 0.01
  },
  "relaxation": {
    "dte_steps": [
      5,
      10
    ],
    "delta_expand_steps": [
      0.02,
      0.04
    ],
    "width_expand_steps": [
      1,
      2
    ],
    "min_credit_of_width_floor": 0.28,
    "max_relax_attempts": 3
  },
  "profiles": {
    "preset": "balanced"
  },
  "user_overrides": {
    "selector.iv_rank_min": 55
  }
}
